-- Checkpoint 250 / V-08: append-only pflegefachliche Abnahme.
-- Lokaler additiver Entwurf; bewusst nicht gegen eine produktive Datenbank ausgeführt.
CREATE TABLE IF NOT EXISTS public.qm_ambulatory_professional_acceptances(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
 review_scope text NOT NULL CHECK(length(btrim(review_scope))>=5),scope_version_id text NOT NULL CHECK(btrim(scope_version_id)<>''),scope_sha256 text NOT NULL CHECK(scope_sha256~'^[0-9a-f]{64}$'),
 required_scenario_ids text[] NOT NULL CHECK(cardinality(required_scenario_ids)>=1),prepared_at timestamptz NOT NULL,prepared_by uuid NOT NULL REFERENCES auth.users(id),prepared_by_name text NOT NULL CHECK(btrim(prepared_by_name)<>''),
 request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),UNIQUE(tenant_id,client_request_id),UNIQUE(tenant_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_ambulatory_professional_acceptance_events(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,acceptance_id uuid NOT NULL REFERENCES public.qm_ambulatory_professional_acceptances(id) ON DELETE RESTRICT,
 sequence_no integer NOT NULL CHECK(sequence_no>=1),event_kind text NOT NULL CHECK(event_kind IN('review_requested','scenario_performed','restriction_recorded','review_decision','reopened')),
 occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL CHECK(recorded_at>=occurred_at),actor_id uuid NOT NULL REFERENCES auth.users(id),actor_name text NOT NULL CHECK(btrim(actor_name)<>''),summary text NOT NULL CHECK(length(btrim(summary))>=5),references_event_ids uuid[] NOT NULL DEFAULT '{}',
 scenario_id text,scenario_title text,scenario_result text CHECK(scenario_result IN('passed','failed','blocked')),reviewer_id uuid,reviewer_name text,reviewer_qualification text,
 restriction_id text,restriction_text text,restriction_owner_id uuid,restriction_owner_name text,restriction_review_due_at timestamptz,
 decision text CHECK(decision IN('accepted','accepted_with_restrictions','not_accepted')),decision_reason text,decision_sha256 text CHECK(decision_sha256~'^[0-9a-f]{64}$'),
 request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),UNIQUE(tenant_id,client_request_id),UNIQUE(acceptance_id,sequence_no),UNIQUE(acceptance_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_ambulatory_professional_acceptance_evidence(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,acceptance_id uuid NOT NULL REFERENCES public.qm_ambulatory_professional_acceptances(id) ON DELETE RESTRICT,event_id uuid NOT NULL REFERENCES public.qm_ambulatory_professional_acceptance_events(id) ON DELETE RESTRICT,
 position_no integer NOT NULL CHECK(position_no>=1),source_type text NOT NULL CHECK(source_type IN('qualification_record','scenario_protocol','decision_record','restriction_record','software_test','other')),
 source_entity_id uuid NOT NULL,source_version_id uuid,record_locator text NOT NULL CHECK(btrim(record_locator)<>''),source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),UNIQUE(event_id,position_no),UNIQUE(event_id,id)
);
ALTER TABLE public.qm_ambulatory_professional_acceptances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qm_ambulatory_professional_acceptance_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qm_ambulatory_professional_acceptance_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.qm_ambulatory_professional_acceptances,public.qm_ambulatory_professional_acceptance_events,public.qm_ambulatory_professional_acceptance_evidence FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.qm_ambulatory_professional_acceptances,public.qm_ambulatory_professional_acceptance_events,public.qm_ambulatory_professional_acceptance_evidence TO authenticated;
DROP POLICY IF EXISTS qm_ambulatory_professional_acceptances_read ON public.qm_ambulatory_professional_acceptances;
CREATE POLICY qm_ambulatory_professional_acceptances_read ON public.qm_ambulatory_professional_acceptances FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_ambulatory_professional_acceptance_events_read ON public.qm_ambulatory_professional_acceptance_events;
CREATE POLICY qm_ambulatory_professional_acceptance_events_read ON public.qm_ambulatory_professional_acceptance_events FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_ambulatory_professional_acceptance_evidence_read ON public.qm_ambulatory_professional_acceptance_evidence;
CREATE POLICY qm_ambulatory_professional_acceptance_evidence_read ON public.qm_ambulatory_professional_acceptance_evidence FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
CREATE OR REPLACE FUNCTION care_private.protect_qm_ambulatory_professional_acceptance_history()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN RAISE EXCEPTION 'Pflegefachliche Abnahmehistorie bleibt append-only.' USING ERRCODE='42501';END$$;
DROP TRIGGER IF EXISTS protect_qm_ambulatory_professional_acceptances ON public.qm_ambulatory_professional_acceptances;
CREATE TRIGGER protect_qm_ambulatory_professional_acceptances BEFORE UPDATE OR DELETE ON public.qm_ambulatory_professional_acceptances FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_ambulatory_professional_acceptance_history();
DROP TRIGGER IF EXISTS protect_qm_ambulatory_professional_acceptance_events ON public.qm_ambulatory_professional_acceptance_events;
CREATE TRIGGER protect_qm_ambulatory_professional_acceptance_events BEFORE UPDATE OR DELETE ON public.qm_ambulatory_professional_acceptance_events FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_ambulatory_professional_acceptance_history();
DROP TRIGGER IF EXISTS protect_qm_ambulatory_professional_acceptance_evidence ON public.qm_ambulatory_professional_acceptance_evidence;
CREATE TRIGGER protect_qm_ambulatory_professional_acceptance_evidence BEFORE UPDATE OR DELETE ON public.qm_ambulatory_professional_acceptance_evidence FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_ambulatory_professional_acceptance_history();

CREATE OR REPLACE FUNCTION public.record_qm_ambulatory_professional_acceptance(p_payload jsonb,p_client_request_id uuid)RETURNS public.qm_ambulatory_professional_acceptances
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();actor uuid:=auth.uid();actor_name text:=public.clinical_actor_name();actual_time timestamptz:=clock_timestamp();result public.qm_ambulatory_professional_acceptances;prior public.qm_ambulatory_professional_acceptances;root_fp text;event_item record;evidence_item record;event_fp text;seq integer;last_occurred_at timestamptz;last_recorded_at timestamptz;last_decision_id uuid;last_reopen integer:=0;request_id uuid;refs uuid[];client_request uuid;scenario_count integer;passed_count integer;restriction_count integer;
BEGIN
 IF t IS NULL OR actor IS NULL OR NOT public.has_permission('qm.close_measure')THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;
 IF p_payload IS NULL OR p_client_request_id IS NULL OR p_payload->>'clientRequestId' IS DISTINCT FROM p_client_request_id::text OR COALESCE(p_payload->>'acceptanceId','')='' OR jsonb_typeof(p_payload->'events')<>'array' OR jsonb_typeof(p_payload->'requiredScenarioIds')<>'array' OR jsonb_array_length(p_payload->'requiredScenarioIds')<1 OR COALESCE(p_payload->>'scopeSha256','')!~'^[0-9a-f]{64}$' OR COALESCE(p_payload->>'preparedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' THEN RAISE EXCEPTION 'Pflegefachliche Abnahmeakte ist unvollständig.' USING ERRCODE='23514';END IF;
 IF(p_payload->>'tenantId')::uuid IS DISTINCT FROM t THEN RAISE EXCEPTION 'Mandant ist widersprüchlich.' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_payload->'requiredScenarioIds')s GROUP BY s HAVING count(*)>1)THEN RAISE EXCEPTION 'Erforderliche Szenarien sind doppelt.' USING ERRCODE='23514';END IF;
 root_fp:=md5(jsonb_build_object('root',p_payload-'events')::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext(p_payload->>'acceptanceId'));
 SELECT*INTO prior FROM public.qm_ambulatory_professional_acceptances WHERE tenant_id=t AND id=(p_payload->>'acceptanceId')::uuid;
 IF FOUND THEN IF prior.request_fingerprint IS DISTINCT FROM root_fp OR prior.client_request_id IS DISTINCT FROM p_client_request_id THEN RAISE EXCEPTION 'Abnahmeidentität wurde anders verwendet.' USING ERRCODE='40001';END IF;result:=prior;
 ELSE
  IF(p_payload->>'preparedBy')::uuid IS DISTINCT FROM actor OR btrim(p_payload->>'preparedByName')IS DISTINCT FROM btrim(actor_name)OR(p_payload->>'preparedAt')::timestamptz>actual_time THEN RAISE EXCEPTION 'Zeitfolge oder Vorbereitungsidentität ist widersprüchlich.' USING ERRCODE='23514';END IF;
  INSERT INTO public.qm_ambulatory_professional_acceptances(id,client_request_id,tenant_id,review_scope,scope_version_id,scope_sha256,required_scenario_ids,prepared_at,prepared_by,prepared_by_name,request_fingerprint)VALUES((p_payload->>'acceptanceId')::uuid,p_client_request_id,t,btrim(p_payload->>'reviewScope'),btrim(p_payload->>'scopeVersionId'),p_payload->>'scopeSha256',ARRAY(SELECT jsonb_array_elements_text(p_payload->'requiredScenarioIds')),(p_payload->>'preparedAt')::timestamptz,actor,actor_name,root_fp)RETURNING*INTO result;
 END IF;
 SELECT COALESCE(max(sequence_no),0),(array_agg(occurred_at ORDER BY sequence_no DESC))[1],(array_agg(recorded_at ORDER BY sequence_no DESC))[1],COALESCE(max(sequence_no)FILTER(WHERE event_kind='reopened'),0) INTO seq,last_occurred_at,last_recorded_at,last_reopen FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND acceptance_id=result.id;
 last_occurred_at:=COALESCE(last_occurred_at,result.prepared_at);last_recorded_at:=COALESCE(last_recorded_at,result.prepared_at);
 SELECT id INTO last_decision_id FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND acceptance_id=result.id AND event_kind='review_decision'AND sequence_no>last_reopen ORDER BY sequence_no DESC LIMIT 1;
 SELECT id INTO request_id FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND acceptance_id=result.id AND event_kind='review_requested' AND sequence_no>last_reopen ORDER BY sequence_no DESC LIMIT 1;
 FOR event_item IN SELECT value,ordinality FROM jsonb_array_elements(p_payload->'events')WITH ORDINALITY LOOP
  event_fp:=md5(event_item.value::text);SELECT client_request_id INTO client_request FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND id=(event_item.value->>'eventId')::uuid;
  IF FOUND THEN IF client_request IS DISTINCT FROM(event_item.value->>'clientRequestId')::uuid OR NOT EXISTS(SELECT 1 FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND id=(event_item.value->>'eventId')::uuid AND request_fingerprint=event_fp)THEN RAISE EXCEPTION 'Verlaufsidentität wurde anders verwendet.' USING ERRCODE='40001';END IF;CONTINUE;END IF;
  IF(event_item.value->>'actorId')::uuid IS DISTINCT FROM actor OR btrim(event_item.value->>'actorName')IS DISTINCT FROM btrim(actor_name)OR COALESCE(event_item.value->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR COALESCE(event_item.value->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'THEN RAISE EXCEPTION 'Verlaufsidentität oder Mikrosekundenzeit ist widersprüchlich.' USING ERRCODE='23514';END IF;
  IF(event_item.value->>'occurredAt')::timestamptz<last_occurred_at OR(event_item.value->>'recordedAt')::timestamptz<(event_item.value->>'occurredAt')::timestamptz OR(event_item.value->>'recordedAt')::timestamptz<last_recorded_at OR(event_item.value->>'recordedAt')::timestamptz>actual_time THEN RAISE EXCEPTION 'Verlauf ist zeitlich widersprüchlich.' USING ERRCODE='23514';END IF;
  refs:=ARRAY(SELECT jsonb_array_elements_text(event_item.value->'referencesEventIds')::uuid);IF EXISTS(SELECT 1 FROM unnest(refs)r LEFT JOIN public.qm_ambulatory_professional_acceptance_events e ON e.id=r AND e.tenant_id=t AND e.acceptance_id=result.id WHERE e.id IS NULL)THEN RAISE EXCEPTION 'Verlaufsreferenz fehlt oder gehört nicht zur Akte.' USING ERRCODE='23503';END IF;
  IF last_decision_id IS NOT NULL AND(event_item.value->>'kind')<>'reopened'THEN RAISE EXCEPTION 'Entschiedene Abnahme benötigt Wiederaufnahme.' USING ERRCODE='23514';END IF;
  IF(event_item.value->>'kind')='review_requested'THEN IF request_id IS NOT NULL OR jsonb_array_length(event_item.value->'evidence')<>0 THEN RAISE EXCEPTION 'Prüfauftrag ist widersprüchlich.' USING ERRCODE='23514';END IF;
  ELSIF(event_item.value->>'kind')='scenario_performed'THEN IF request_id IS NULL OR NOT request_id=ANY(refs)OR NOT((p_payload->'requiredScenarioIds')?COALESCE(event_item.value->>'scenarioId',''))OR COALESCE(event_item.value->>'scenarioResult','')NOT IN('passed','failed','blocked')OR(event_item.value->>'reviewerId')::uuid IS DISTINCT FROM actor OR btrim(COALESCE(event_item.value->>'reviewerName',''))IS DISTINCT FROM btrim(actor_name)OR btrim(COALESCE(event_item.value->>'reviewerQualification',''))=''OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='qualification_record')OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='scenario_protocol')THEN RAISE EXCEPTION 'Reales Szenario benötigt Prüfauftrag, tatsächliche Prüferidentität, Qualifikation und Protokoll.' USING ERRCODE='23514';END IF;
  ELSIF(event_item.value->>'kind')='restriction_recorded'THEN IF request_id IS NULL OR NOT request_id=ANY(refs)OR COALESCE(event_item.value->>'restrictionId','')=''OR COALESCE(event_item.value->>'restrictionOwnerId','')=''OR(event_item.value->>'restrictionReviewDueAt')::timestamptz<=(event_item.value->>'occurredAt')::timestamptz OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='restriction_record')THEN RAISE EXCEPTION 'Einschränkung benötigt Verantwortung, Prüffrist und Originalbeleg.' USING ERRCODE='23514';END IF;
  ELSIF(event_item.value->>'kind')='review_decision'THEN
   IF request_id IS NULL OR NOT request_id=ANY(refs)OR COALESCE(event_item.value->>'decision','')NOT IN('accepted','accepted_with_restrictions','not_accepted')OR(event_item.value->>'reviewerId')::uuid IS DISTINCT FROM actor OR btrim(COALESCE(event_item.value->>'reviewerName',''))IS DISTINCT FROM btrim(actor_name)OR btrim(COALESCE(event_item.value->>'reviewerQualification',''))=''OR COALESCE(event_item.value->>'decisionSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='qualification_record')OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='decision_record')THEN RAISE EXCEPTION 'Abnahmeentscheidung benötigt tatsächliche qualifizierte Person und Entscheidungsoriginal.' USING ERRCODE='23514';END IF;
   SELECT count(*),count(*)FILTER(WHERE scenario_result='passed')INTO scenario_count,passed_count FROM(SELECT DISTINCT ON(scenario_id)scenario_id,scenario_result FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND acceptance_id=result.id AND event_kind='scenario_performed'AND sequence_no>last_reopen ORDER BY scenario_id,sequence_no DESC)s;
   SELECT count(*)INTO restriction_count FROM public.qm_ambulatory_professional_acceptance_events WHERE tenant_id=t AND acceptance_id=result.id AND event_kind='restriction_recorded'AND sequence_no>last_reopen;
   IF event_item.value->>'decision'<>'not_accepted'AND(scenario_count<>cardinality(result.required_scenario_ids)OR passed_count<>cardinality(result.required_scenario_ids)OR EXISTS(SELECT 1 FROM public.qm_ambulatory_professional_acceptance_events e WHERE e.tenant_id=t AND e.acceptance_id=result.id AND e.event_kind='scenario_performed'AND e.sequence_no>last_reopen AND NOT e.id=ANY(refs)))THEN RAISE EXCEPTION 'Softwaretests ersetzen keine vollständigen tatsächlich bestandenen und referenzierten Szenarien.' USING ERRCODE='23514';END IF;
   IF event_item.value->>'decision'='accepted'AND restriction_count>0 OR event_item.value->>'decision'='accepted_with_restrictions'AND restriction_count=0 THEN RAISE EXCEPTION 'Abnahmeentscheidung und Einschränkungen sind widersprüchlich.' USING ERRCODE='23514';END IF;
  ELSIF(event_item.value->>'kind')='reopened'THEN IF last_decision_id IS NULL OR cardinality(refs)<>1 OR refs[1]<>last_decision_id OR jsonb_array_length(event_item.value->'evidence')<>0 THEN RAISE EXCEPTION 'Wiederaufnahme ist nur nach Entscheidung zulässig.' USING ERRCODE='23514';END IF;
  ELSE RAISE EXCEPTION 'Unbekannte Verlaufsart.' USING ERRCODE='23514';END IF;
  seq:=seq+1;INSERT INTO public.qm_ambulatory_professional_acceptance_events(id,client_request_id,tenant_id,acceptance_id,sequence_no,event_kind,occurred_at,recorded_at,actor_id,actor_name,summary,references_event_ids,scenario_id,scenario_title,scenario_result,reviewer_id,reviewer_name,reviewer_qualification,restriction_id,restriction_text,restriction_owner_id,restriction_owner_name,restriction_review_due_at,decision,decision_reason,decision_sha256,request_fingerprint)VALUES((event_item.value->>'eventId')::uuid,(event_item.value->>'clientRequestId')::uuid,t,result.id,seq,event_item.value->>'kind',(event_item.value->>'occurredAt')::timestamptz,(event_item.value->>'recordedAt')::timestamptz,actor,actor_name,btrim(event_item.value->>'summary'),refs,NULLIF(btrim(COALESCE(event_item.value->>'scenarioId','')),''),NULLIF(btrim(COALESCE(event_item.value->>'scenarioTitle','')),''),NULLIF(event_item.value->>'scenarioResult',''),NULLIF(event_item.value->>'reviewerId','')::uuid,NULLIF(btrim(COALESCE(event_item.value->>'reviewerName','')),''),NULLIF(btrim(COALESCE(event_item.value->>'reviewerQualification','')),''),NULLIF(btrim(COALESCE(event_item.value->>'restrictionId','')),''),NULLIF(btrim(COALESCE(event_item.value->>'restrictionText','')),''),NULLIF(event_item.value->>'restrictionOwnerId','')::uuid,NULLIF(btrim(COALESCE(event_item.value->>'restrictionOwnerName','')),''),NULLIF(event_item.value->>'restrictionReviewDueAt','')::timestamptz,NULLIF(event_item.value->>'decision',''),NULLIF(btrim(COALESCE(event_item.value->>'decisionReason','')),''),NULLIF(event_item.value->>'decisionSha256',''),event_fp);
  FOR evidence_item IN SELECT value,ordinality FROM jsonb_array_elements(event_item.value->'evidence')WITH ORDINALITY LOOP IF COALESCE(evidence_item.value->>'sourceType','')NOT IN('qualification_record','scenario_protocol','decision_record','restriction_record','software_test','other')OR btrim(COALESCE(evidence_item.value->>'recordLocator',''))=''OR COALESCE(evidence_item.value->>'sourceSha256','')!~'^[0-9a-f]{64}$'THEN RAISE EXCEPTION 'Beleg ist unvollständig.' USING ERRCODE='23514';END IF;INSERT INTO public.qm_ambulatory_professional_acceptance_evidence(id,tenant_id,acceptance_id,event_id,position_no,source_type,source_entity_id,source_version_id,record_locator,source_sha256)VALUES((evidence_item.value->>'evidenceId')::uuid,t,result.id,(event_item.value->>'eventId')::uuid,evidence_item.ordinality,evidence_item.value->>'sourceType',(evidence_item.value->>'sourceEntityId')::uuid,NULLIF(evidence_item.value->>'sourceVersionId','')::uuid,btrim(evidence_item.value->>'recordLocator'),evidence_item.value->>'sourceSha256');END LOOP;
  last_occurred_at:=(event_item.value->>'occurredAt')::timestamptz;last_recorded_at:=(event_item.value->>'recordedAt')::timestamptz;IF event_item.value->>'kind'='review_requested'THEN request_id:=(event_item.value->>'eventId')::uuid;ELSIF event_item.value->>'kind'='review_decision'THEN last_decision_id:=(event_item.value->>'eventId')::uuid;ELSIF event_item.value->>'kind'='reopened'THEN last_reopen:=seq;request_id:=NULL;last_decision_id:=NULL;END IF;
 END LOOP;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)VALUES(t,NULL,'qm_ambulatory_professional_acceptance',result.id,'professional_acceptance_recorded','Pflegefachliche Abnahme append-only fortgeschrieben; Softwaretests bleiben ergänzend und erzeugen keine Fachfreigabe.',to_jsonb(result),actor,actor_name);RETURN result;
END$$;
REVOKE ALL ON FUNCTION public.record_qm_ambulatory_professional_acceptance(jsonb,uuid)FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_qm_ambulatory_professional_acceptance(jsonb,uuid)TO authenticated;
